def is_expired(self, now: Optional[float] = None) -> bool:
    """Returns True if entry has an expiration timestamp and current time >= expires_at."""
    if now is None:
        now = time.time()
    if self.expires_at is not None and now >= self.expires_at:
        return True
    return False

def get(self, key: str) -> Optional[str]:
    """Returns the value for key. If key is missing or expired, removes it if expired and returns None."""
    import time
    entry = self._store.get(key)
    if entry is None:
        return None
    if entry.expires_at is not None and time.time() >= entry.expires_at:
        del self._store[key]
        return None
    return entry.value

def export_json(self) -> str:
    """Returns a JSON string of all currently unexpired key -> value mappings."""
    import json
    result = []
    for key, entry in self._store.items():
        if entry.expires_at is None or time.time() < entry.expires_at:
            result.append({"key": key, "value": entry.value})
    return json.dumps(result, indent=2)

def import_json(self, json_str: str) -> int:
    """Loads key -> value pairs from a JSON string into store. Returns count of loaded keys."""
    import json
    entries = json.loads(json_str)
    for item in entries:
        key = item["key"]
        value = item["value"]
        self.set(key, value, ttl_seconds=None)
    return len(entries)
